WITH unpacked AS (SELECT id, plan, effective_from, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT id, effective_from, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY entry_price, id) AS event_seq, LAST_VALUE(entry_price, TRUE) OVER (PARTITION BY plan ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_entry_price FROM unpacked WHERE effective_from < '2023-07-01';
